<script>
import {profile,data} from '../lib/store.js';import {academicSummary,creditSum} from '../lib/model.js';import {TASKS,DEADLINES} from '../lib/catalog.js';import Icon from '../lib/components/Icon.svelte';import Schedule from '../lib/components/Schedule.svelte';
let summary=$derived(academicSummary($profile,$data));let scheduleTerm=$state('fall-2026');
let nextClasses=$derived($data.enrolledByTerm['spring-2027']??[]);let cartCount=$derived(($data.cartByTerm['spring-2027']??[]).length);
const essentials=[{title:'Classes & schedule',description:'Find your next class',icon:'calendar',href:'#/classes'},{title:'My Academics',description:'Your records, progress & graduation',icon:'book',href:'#/academics'},{title:'Student finances',description:'Account & financial aid',icon:'wallet',href:'#/finances'},{title:'Tasks & reminders',description:'Your next steps, in order',icon:'check',href:'#/tasks'},{title:'Scholarships',description:'Explore opportunities',icon:'star',href:'#/scholarships'},{title:'Academic services',description:'Find the right support',icon:'grid',href:'#/services'}];
</script>
<div class="page-heading"><div><p class="eyebrow">Your student workspace</p><h1>Your day, at a glance.</h1><p>Welcome back, {$profile.name.split(' ')[0]}. A little clarity for what comes next.</p></div><span class="term-pill"><span class="status-dot"></span>Fall 2026</span></div>
<section class="welcome-banner"><div class="banner-orbit" aria-hidden="true"><img src="./uc-monogram.svg" alt="" width="240" height="209"/></div><div><p class="eyebrow">A new semester starts with a plan</p><h2>Make room for what’s next.</h2><p>Spring registration is open. Find the right classes, compare your options, and enroll with confidence.</p><a href="#/classes?term=spring-2027" class="button gold">{nextClasses.length?'Review your spring schedule':'Plan your spring semester'}<Icon name="arrow" size={17}/></a></div><div class="banner-stat"><strong>{nextClasses.length||cartCount||'01'}</strong><span>{nextClasses.length?'classes enrolled for spring':cartCount?'classes in your planning cart':'clear place to start'}</span></div></section>
<div class="home-grid"><aside class="profile-panel panel"><span class="eyebrow">Student profile</span><div class="avatar large">{$profile.initials}</div><h2>{$profile.name}</h2><p>{$profile.major} · {$profile.degree}</p><p class="muted small">{$profile.college}</p><div class="tags"><span class="badge neutral">{$profile.year}</span><span class="badge success">{summary.underway>=12?'Full-time':'Part-time'}</span></div><dl class="profile-numbers"><div><dt>Cumulative GPA</dt><dd>{summary.gpa??'—'}</dd></div><div><dt>Earned credits</dt><dd>{summary.earned}</dd></div><div><dt>In progress</dt><dd>{summary.underway}</dd></div></dl><a href="#/profile" class="button secondary full">View my profile<Icon name="arrow" size={15}/></a><div class="profile-note"><Icon name="shield" size={16}/><p>Demo student · changes are saved in this browser only.</p></div></aside>
 <div><div class="section-heading"><div><h2>Your student essentials</h2><p class="muted small">The things you need, a little easier to find.</p></div></div><div class="essentials-grid">{#each essentials as item}<a class="essential panel" href={item.href}><span class="tile-icon"><Icon name={item.icon}/></span><Icon name="external" size={13}/><strong>{item.title}</strong><p>{item.description}</p>{#if item.href==='#/tasks'}<span class="tile-count">{TASKS.length-$data.completedTasks.length}</span>{/if}</a>{/each}</div>
 <section class="panel schedule-panel"><div class="section-heading"><h2>Your class schedule</h2><a href={`#/classes?tab=schedule&term=${scheduleTerm}`} class="text-link">Manage classes<Icon name="arrow" size={15}/></a></div><div class="schedule-term"><label for="home-term">Semester</label><select id="home-term" bind:value={scheduleTerm}><option value="fall-2026">Fall 2026 · Current</option><option value="spring-2027">Spring 2027 · Next</option></select><span class="muted small">{creditSum($data.enrolledByTerm[scheduleTerm]??[])} enrolled credits</span></div><Schedule courses={$data.enrolledByTerm[scheduleTerm]??[]} termId={scheduleTerm} compact={$data.preferences.compactSchedule}/></section></div>
</div>
<div class="bottom-grid"><section class="panel padded"><div class="section-heading"><h2>On your horizon</h2><a href="#/services?category=Planning" class="text-link">All dates<Icon name="arrow" size={15}/></a></div>{#each DEADLINES as d}<div class="deadline-row"><div class="date-tile"><strong>{d.day}</strong><span>{d.month}</span></div><div><strong>{d.title}</strong><p class="muted small">{d.detail}</p></div>{#if d.done}<span class="badge success">Open</span>{/if}</div>{/each}</section><section class="advisor-panel"><span class="tile-icon"><Icon name="people" size={25}/></span><p class="eyebrow">You don’t have to figure it out alone</p><h2>A little guidance goes a long way.</h2><p>Your advisor can help connect your next class to your bigger picture.</p><a class="button secondary" href="#/services?category=Advising">Find advising support<Icon name="arrow" size={16}/></a></section></div>
